  function setSpot(){const p=spots[Math.floor(Math.random()*spots.length)];target.setAttribute('transform',`translate(${p[0]} ${p[1]})`);}
  function locate(e){const p=svg.createSVGPoint();p.x=e.clientX;p.y=e.clientY;const m=p.matrixTransform(svg.getScreenCTM().inverse());return {x:m.x,y:m.y};}
  function showToast(text){toast.textContent=text;toast.classList.remove('show');void toast.offsetWidth;toast.classList.add('show');}
